<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Ujian — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;padding:30px 20px;background:linear-gradient(135deg,#f4f7fb,#e8eef7);overflow-x:hidden}body:before,body:after{content:"✦";position:fixed;z-index:-1;font-size:230px;line-height:1;color:#a0b4d14b}body:before{left:-55px;top:10%}body:after{right:-50px;bottom:0;color:#365d9227}.wrap{max-width:1100px;margin:auto}.nav{display:flex;gap:10px;flex-wrap:wrap}.nav a{padding:10px 13px;background:#fff9;border:1px solid #fff;border-radius:10px;color:#23395d;text-decoration:none;font-size:13px;font-weight:800}.hero{position:relative;overflow:hidden;margin:18px 0;padding:29px 30px;border-radius:22px;background:linear-gradient(115deg,#23395d,#365d92);color:#fff;box-shadow:0 16px 35px #23395d29}.hero:after{content:"✦";position:absolute;font-size:175px;color:#ffffff17;right:25px;top:-55px}.hero h1,.hero p{position:relative}.hero h1{margin:0 0 7px;font-size:28px}.hero p{margin:0;color:#e7effa;max-width:640px;line-height:1.6}.success{margin:15px 0;padding:12px 14px;color:#166534;background:#dcfce7;border-radius:11px}.card{margin:18px 0;padding:22px;background:#fffd;border:1px solid #fff;border-radius:18px;box-shadow:0 14px 30px #23395d12}.card h2{margin:0 0 5px;color:#23395d}.muted{margin:0 0 17px;color:#64748b;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:7px;margin:11px 0}.field label{color:#475569;font-size:11px;font-weight:800;letter-spacing:.4px}input{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:10px;font:inherit;background:#fff;outline:0}input:focus{border-color:#365d92;box-shadow:0 0 0 4px #a0b4d140}.questions{max-height:275px;overflow:auto;border:1px solid #dbe5f0;border-radius:12px;background:#f8fafc}.questions label{display:block;padding:11px 13px;border-bottom:1px solid #e5edf5;cursor:pointer;font-size:13px}.questions label:hover{background:#e8eef7}.button{border:0;border-radius:10px;padding:10px 13px;background:#23395d;color:#fff;font:700 13px Inter;cursor:pointer;box-shadow:0 7px 14px #23395d24}.secondary{background:#e8eef7;color:#23395d;box-shadow:none}.delete{background:#b91c1c}.exam{position:relative;padding:18px 0;border-bottom:1px solid #e3ebf3}.exam:last-child{border:0}.exam-title{font-size:16px;color:#23395d}.exam small{color:#64748b;line-height:1.7}.token{display:inline-block;margin:9px 0;padding:8px 12px;border-radius:9px;letter-spacing:2px;font-size:18px;font-weight:800;color:#23395d;background:#e8eef7}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.actions form{display:inline}@media(max-width:640px){body{padding:20px 14px}.grid{grid-template-columns:1fr}.hero{padding:24px}.hero h1{font-size:24px}}</style></head><body><main class="wrap"><nav class="nav"><a href="{{ route('dashboard') }}">← Dashboard</a><a href="{{ route('teacher.questions') }}">✎ Bank Soal</a><a href="{{ route('teacher.results') }}">◉ Hasil Ujian</a></nav><section class="hero"><h1>Kelola Ujian & Token</h1><p>Rangkai soal menjadi ujian, tentukan jadwalnya, lalu bagikan token unik kepada siswa.</p></section>@if(session('success'))<p class="success">✓ {{ session('success') }}</p>@endif<section class="card"><h2>Buat Ujian Baru</h2><p class="muted">Pilih soal dari Bank Soal untuk membuat satu sesi ujian.</p>@if($questions->isEmpty())<p class="muted">Belum ada soal. <a href="{{ route('teacher.questions') }}">Buat soal di Bank Soal terlebih dahulu.</a></p>@else<form method="post" action="{{ route('teacher.exams.store') }}">@csrf<div class="grid"><div class="field"><label>NAMA UJIAN</label><input name="title" required></div><div class="field"><label>MATA PELAJARAN</label><input name="subject" required></div><div class="field"><label>DURASI (MENIT)</label><input type="number" name="duration_minutes" value="60" min="1" required></div><div class="field"><label>BERLAKU SAMPAI</label><input type="datetime-local" name="expires_at" required></div></div><p><strong>Pilih soal untuk ujian ini</strong></p><div class="questions">@foreach($questions as $question)<label><input type="checkbox" name="question_ids[]" value="{{ $question->id }}"> <strong>{{ $question->subject }}</strong> · {{ $question->question_text }}</label>@endforeach</div><p><button class="button">Buat Ujian & Token ✦</button></p></form>@endif</section><section class="card"><h2>Ujian Saya</h2><p class="muted">Token dapat diperbarui kapan saja jika perlu.</p>@forelse($exams as $exam)<article class="exam"><strong class="exam-title">{{ $exam->title }}</strong> · {{ $exam->subject }}<br><small>Durasi {{ $exam->duration_minutes }} menit · berlaku sampai {{ $exam->expires_at }}</small><br><span class="token">{{ $exam->token }}</span><div class="actions"><form method="post" action="{{ route('teacher.exams.token',$exam->id) }}" onsubmit="return confirm('Buat token baru? Token lama tidak dapat dipakai lagi.')">@csrf @method('PATCH')<button class="button secondary">Buat Token Baru</button></form><form method="post" action="{{ route('teacher.exams.toggle',$exam->id) }}">@csrf @method('PATCH')<button class="button">{{ $exam->is_active ? 'Nonaktifkan' : 'Aktifkan' }}</button></form><form method="post" action="{{ route('teacher.exams.destroy',$exam->id) }}" onsubmit="return confirm('Hapus ujian ini?')">@csrf @method('DELETE')<button class="button delete">Hapus</button></form></div></article>@empty<p class="muted">Belum ada ujian. Buat ujian untuk memperoleh token siswa.</p>@endforelse</section></main></body></html>
